// 2D travel chart: cartridge travel vs button travel, for both rest states.
// Curves are generated by running the real mechanism model (step/pose), not hand-drawn.
import { createInitialState, step, pose, deriveGeometry } from '../mechanism/mechanism.js';
import { DEFAULT_PARAMS as P } from '../mechanism/params.js';

function ascendingCurve(from, n = 120) {
  const pts = [];
  let s = from;
  for (let i = 0; i <= n; i++) {
    s = step(s, i / n);
    const p = pose(s);
    pts.push([p.buttonTravelMm, p.cartridgeTravelMm]);
  }
  return pts;
}

export function travelCurves() {
  let s = createInitialState();
  const retracted = ascendingCurve(s);
  for (let i = 0; i <= 100; i++) s = step(s, i / 100);
  for (let i = 100; i >= 0; i--) s = step(s, i / 100);
  return { retracted, extended: ascendingCurve(s) };
}

export function createChart(canvas) {
  const curves = travelCurves();
  const g = deriveGeometry(P);
  const S = P.buttonStrokeMm;
  const ctx = canvas.getContext('2d');
  const css = (n) => getComputedStyle(document.documentElement).getPropertyValue(n).trim() || '#333';

  return {
    draw(p) {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const w = canvas.clientWidth, h = canvas.clientHeight;
      if (canvas.width !== Math.round(w * dpr)) { canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr); }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      const m = { l: 34, r: 8, t: 8, b: 26 };
      const X = (v) => m.l + (v / S) * (w - m.l - m.r);
      const Y = (v) => h - m.b - (v / S) * (h - m.t - m.b);
      ctx.font = '10px system-ui, sans-serif';
      ctx.lineWidth = 1;
      ctx.strokeStyle = css('--line'); ctx.fillStyle = css('--muted');
      ctx.strokeRect(m.l, m.t, w - m.l - m.r, h - m.t - m.b);
      ctx.fillText('button travel (mm)', m.l + 40, h - 8);
      ctx.save(); ctx.translate(10, h - m.b - 4); ctx.rotate(-Math.PI / 2); ctx.fillText('cartridge (mm)', 0, 0); ctx.restore();
      ctx.setLineDash([3, 3]);
      for (const [u, label, side] of [[g.uRelease, 'release', -1], [g.uEngage, 'engage', 1]]) {
        ctx.beginPath(); ctx.moveTo(X(u * S), m.t); ctx.lineTo(X(u * S), h - m.b); ctx.stroke();
        ctx.fillText(label, X(u * S) + (side < 0 ? -ctx.measureText(label).width - 3 : 3), h - m.b - 5);
      }
      ctx.setLineDash([]);
      const plot = (pts, color, width) => {
        ctx.beginPath(); pts.forEach(([x, y], i) => (i ? ctx.lineTo(X(x), Y(y)) : ctx.moveTo(X(x), Y(y))));
        ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
      };
      plot(curves.retracted, css('--muted'), 1.5);
      plot(curves.extended, css('--ink'), 1.5);
      ctx.fillStyle = css('--accent');
      ctx.beginPath(); ctx.arc(X(p.buttonTravelMm), Y(p.cartridgeTravelMm), 4.5, 0, Math.PI * 2); ctx.fill();
    },
  };
}
